const PU_ALARME_LACT = ["Temperatura na axila de 37,8 °C ou mais, ou abaixo de 35,5 °C, em bebê com menos de 3 meses","Dificuldade para respirar, gemência ou costelas aparecendo","Bebê muito mole, sonolento demais ou difícil de acordar","Recusa de mamar ou vômitos repetidos","Pele ou olhos amarelos que aumentam, ou pele arroxeada","Convulsão","Menos de 6 fraldas molhadas por dia depois do 5º dia de vida"];
const PU_ALARME_CRIANCA = ["Dificuldade para respirar ou respiração muito rápida","Criança muito sonolenta, irritada demais ou que não brinca","Vômitos que não param ou não consegue beber","Convulsão","Manchas roxas pelo corpo com febre","Sinais de desidratação: boca seca, pouco xixi, choro sem lágrimas"];
