function pu(o){
  const fontes = ["caderneta_crianca","pni2026","marcos_cad","acidentes", ...(o.fontes||[])];
  return {
    id: o.id, modulo: "pu", nome: o.nome, sistema: "Consultas por idade", risco: "baixo",
    ciap: "A98", cid: "Z00.1",
    tags: "puericultura consulta de rotina criança lactente crescimento desenvolvimento vacinas " + (o.tags||""),
    S: `Criança de ${o.idade}${o.idadeExtra||""}, comparece à consulta de puericultura acompanhada de ___.\nAlimentação: ${o.alim}\nSono: ___ (${o.sono||"local e posição"}). Eliminações: diurese ___ | evacuações ___.\nIntercorrências desde a última consulta: ___. Medicações/suplementos: ___.\nDesenvolvimento referido pela família: ___. Preocupações da família: ___.\nContexto: rede de apoio ___ | creche/escola ___ | exposição a tabaco ___ | violência ___.`,
    O: `Peso ___ g/kg (escore-z ___) | Comprimento/estatura ___ cm (escore-z ___) | PC ___ cm (escore-z ___)${o.imc?" | IMC/idade escore-z ___":""}\nTax ___ °C | FC ___ bpm | FR ___ irpm\nEstado geral ___. ${o.exame}\nMarcos do desenvolvimento (Caderneta): ${o.marcos.join("; ")} – ___ (presentes / ausentes: ___).\nCaderneta de vacinação: ___ (em dia / pendências: ___).`,
    A: `Criança de ${o.idade}, crescimento ___ (adequado / ___) e desenvolvimento ___ (adequado para a idade / alerta / provável atraso). Alimentação ___. Vacinação ___.`,
    P: `- Curvas de crescimento da Caderneta preenchidas (peso, comprimento, PC${o.imc?", IMC":""}).\n- Marcos do desenvolvimento registrados.\n${o.plano}\n- Vacinas: ${o.vac}\n- Prevenção de acidentes e sono seguro orientados.\n- Sinais de alerta orientados.\n- Próxima consulta: ${o.prox}.`,
    roteiro: [
      {g: "Marcos esperados nesta faixa (Caderneta)", nota: "Ausência de marcos da faixa anterior = provável atraso; ausência de marcos da faixa atual = alerta: orientar estímulo e reavaliar em 30 dias.", i: o.marcos},
      {g: "Checklist da consulta", i: o.check},
      {g: "Vacinas (PNI 2026)", i: [o.vac]},
      {g: "Prevenção de acidentes", i: o.acid}
    ],
    rx: o.rx || [],
    orient: o.orient,
    alarme: o.alarme || PU_ALARME_CRIANCA,
    encaminhar: o.enc || "Atraso de desenvolvimento, desvio de crescimento ou alteração ao exame → ver itens específicos do módulo. Sinais de gravidade → urgência pediátrica.",
    sus: PU_SUS,
    evid: {resumo: o.evid || "O acompanhamento da criança com avaliação de crescimento, desenvolvimento, alimentação, imunização e prevenção de acidentes nas idades da Caderneta é a base da puericultura na APS. A maior parte das recomendações é normativa (MS) ou de consenso (SBP).", certeza: "Recomendação normativa/consenso", fontes},
    mudancas: o.mud || [],
    nv: ["Marcos do desenvolvimento: conferir o texto exato do instrumento da Caderneta 2025.", ...(o.nv||[])]
  };
}

